package com.lifeos.events; import com.lifeos.events.dto.*; import com.lifeos.shared.exception.*; import com.lifeos.users.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class EventService {private final EventRepository repo;private final UserRepository users;public EventService(EventRepository r,UserRepository u){repo=r;users=u;}private User user(String e){return users.findByEmail(e).orElseThrow(()->new ResourceNotFoundException("User not found"));}private Event owned(Long id,String e){return repo.findByIdAndUserId(id,user(e).getId()).orElseThrow(()->new ResourceNotFoundException("Event not found"));}public List<EventResponse> list(String e){return repo.findAllByUserIdOrderByStartDateTimeAsc(user(e).getId()).stream().map(EventResponse::from).toList();}public EventResponse get(Long id,String e){return EventResponse.from(owned(id,e));}public EventResponse create(EventRequest r,String e){Event v=new Event();v.setUser(user(e));apply(v,r);return EventResponse.from(repo.save(v));}public EventResponse update(Long id,EventRequest r,String e){Event v=owned(id,e);apply(v,r);return EventResponse.from(repo.save(v));}public void delete(Long id,String e){repo.delete(owned(id,e));}private void apply(Event v,EventRequest r){if(!r.endDateTime().isAfter(r.startDateTime()))throw new BadRequestException("endDateTime must be after startDateTime");v.setTitle(r.title().trim());v.setDescription(r.description());v.setStartDateTime(r.startDateTime());v.setEndDateTime(r.endDateTime());v.setLocation(r.location());}}
